// At-least-once delivery means the same event can arrive twice. Static data
// survives across executions of an active workflow, so it is the dedupe set.
const state = $getWorkflowStaticData('global');
state.seen = state.seen || {};
const webhook = $('Webhook').first().json;
const eventId = webhook.headers['x-botvy-event-id'];
if (!eventId || state.seen[eventId]) {
  // Returning no items ends the run here: a repeat leaves one execution with output.
  return [];
}
state.seen[eventId] = Date.now();
// Keep the set bounded: forget the oldest once it grows past a thousand.
const ids = Object.keys(state.seen);
if (ids.length > 1000) {
  ids.sort((a, b) => state.seen[a] - state.seen[b]).slice(0, ids.length - 1000).forEach((id) => delete state.seen[id]);
}
let body = webhook.body;
try { body = JSON.parse(Buffer.from($('Webhook').first().binary.data.data, 'base64').toString('utf8')); } catch {}
return [{ json: { eventId, event: webhook.headers['x-botvy-event'], body } }];
